static float exGet(const Car &c, int k) {
  switch (k) {
    case 0: return c.oil;
    case 1: return c.filt;
    case 2: return c.bfl;
    case 3: return c.pads;
    case 4: return c.disc;
    case 5: return c.tires;
    default: return c.bal;
  }
}
static void exSet(Car &c, int k, float v) {
  switch (k) {
    case 0: c.oil = v; break;
    case 1: c.filt = v; break;
    case 2: c.bfl = v; break;
    case 3: c.pads = v; break;
    case 4: c.disc = v; break;
    case 5: c.tires = v; break;
    default: c.bal = v; break;
  }
}
