          drawBox(LC(0.7f * s2, hy - 0.052f, zf + 0.022f), v3(0.22f, 0.008f, 0.01f), heading, chr, true);          // хром под фарой
          drawBox(LC(0.94f * s2, hy + 0.07f, zf - 0.12f), v3(0.014f, 0.085f, 0.11f), heading, lens, false);        // загиб фары на крыло
