      button(rt.x, rt.y, rt.w, rt.h, holdT ? "МЕНЯЮ ШИНЫ..." : (haveT > 0 ? "Держи - менять шины" : "Нет шин! Закажи"), car.tires < 95.0f && haveT > 0, holdT ? RGB(90, 200, 120) : RGB(60, 150, 90));
      if (holdT) tprog += dt * 0.45f; else tprog = 0;
      fillRect(x, y + bh + fs * 2, w, fs * 5, RGB(16, 16, 22));
