      else drawText(x, y, "ЛУЧШЕ СДЕЛАТЬ БАЛАНСИРОВКУ", fs, RGB(255, 210, 90), 0);
      y += fs * 10;
      drawText(x, y, "ДЕРЖИ КНОПКУ, ПОКА КРУТЯТСЯ", fs, RGB(170, 190, 220), 0);
      y += fs * 12;
